                0x5a, 0x31, 0xb8, 0xa1, 0x1f, 0x5c, 0x5e, 0xe1, 0x87, 0x9e, 0xc3, 0x45, 0x4e, 0x5f,
                0x3c, 0x73, 0x8d, 0x2d, 0x9d, 0x20, 0x13, 0x95, 0xfa, 0xa4, 0xb6, 0x1a, 0x96, 0xc8,
            ]
        );
    }

    #[test]
    fn direction_derivation_matches_v3_vectors() {
        let udp_ikm = hkdf_sha256(&MASTER_KEY, &SESSION_SALT, b"erd/udp-ikm/v3", 32);
        assert_eq!(
            hkdf_sha256(&udp_ikm, &SESSION_SALT, b"erd/udp-c2h/v3", 32),
            [
                0x7b, 0x6b, 0xe7, 0xd1, 0xaa, 0xe9, 0xb3, 0xd2, 0x3a, 0x4c, 0xb7, 0xcc, 0x9b, 0x56,
                0x44, 0xcd, 0x88, 0x89, 0x38, 0xdc, 0x81, 0x29, 0x1b, 0x6e, 0x7f, 0x76, 0x98, 0x08,
                0x37, 0xa0, 0x79, 0x99,
            ]
        );
        assert_eq!(
            hkdf_sha256(&udp_ikm, &SESSION_SALT, b"erd/udp-c2h/v3/nonce", 4),
            [0xe2, 0x6c, 0x23, 0xc1]
        );
        assert_eq!(
            hkdf_sha256(&udp_ikm, &SESSION_SALT, b"erd/udp-h2c/v3", 32),
            [
                0x13, 0x56, 0x91, 0xaf, 0x33, 0x8c, 0x20, 0x5f, 0x66, 0x92, 0x40, 0xb4, 0x6b, 0xc4,
                0x34, 0x86, 0x8d, 0x85, 0xfa, 0x66, 0xf8, 0x36, 0xe0, 0x10, 0xf9, 0x1d, 0x27, 0x05,
                0xac, 0xc9, 0xa5, 0x16,
            ]
        );
        assert_eq!(
            hkdf_sha256(&udp_ikm, &SESSION_SALT, b"erd/udp-h2c/v3/nonce", 4),
            [0xcb, 0xbf, 0xd2, 0xe6]
        );
    }

    #[test]
    fn seal_open_round_trip() {
        let (mut sender, mut receiver) = matching_pair();
        let plaintext = (0..1000).map(|n| (n % 251) as u8).collect::<Vec<_>>();
        let datagram = sender.seal(&plaintext, AAD).unwrap();
        assert_eq!(datagram.len(), plaintext.len() + NONCE_SIZE + TAG_SIZE);
        assert_eq!(receiver.open(&datagram, AAD).unwrap(), plaintext);
    }

    #[test]
    fn tampered_datagram_rejected() {
        let (mut sender, mut receiver) = matching_pair();
        let mut datagram = sender.seal(b"payload", AAD).unwrap();
        *datagram.last_mut().unwrap() ^= 0xff;
        assert!(matches!(
            receiver.open(&datagram, AAD),
            Err(DatagramError::Authentication)
        ));
    }

    #[test]
    fn aad_mismatch_rejected() {
        let (mut sender, mut receiver) = matching_pair();
        let datagram = sender.seal(b"payload", AAD).unwrap();
        assert!(matches!(
            receiver.open(&datagram, b"different"),
            Err(DatagramError::Authentication)
        ));
    }

    #[test]
    fn duplicate_datagram_rejected() {
        let (mut sender, mut receiver) = matching_pair();
        let datagram = sender.seal(b"once", AAD).unwrap();
        assert_eq!(receiver.open(&datagram, AAD).unwrap(), b"once");
        assert!(matches!(
            receiver.open(&datagram, AAD),
            Err(DatagramError::Replay)
        ));
    }

    #[test]
    fn stale_datagram_outside_window_rejected() {
        let (mut sender, mut receiver) = matching_pair();
        let mut first = Vec::new();
        let mut latest = Vec::new();
        for index in 0..=REPLAY_WINDOW_SIZE + 8 {
            let datagram = sender.seal(b"stale", AAD).unwrap();
            if index == 0 {
                first = datagram.clone();
            }
            latest = datagram;
        }
        assert_eq!(receiver.open(&latest, AAD).unwrap(), b"stale");
        assert!(matches!(
            receiver.open(&first, AAD),
            Err(DatagramError::Replay)
        ));
    }

    #[test]
    fn direction_keys_are_incompatible() {
        let mut sender =
            DatagramCipher::derive(&MASTER_KEY, &SESSION_SALT, Direction::ClientToHost).unwrap();
        let mut wrong_receiver =
            DatagramCipher::derive(&MASTER_KEY, &SESSION_SALT, Direction::HostToClient).unwrap();
        let datagram = sender.seal(b"cross", AAD).unwrap();
        assert!(matches!(
            wrong_receiver.open(&datagram, AAD),
            Err(DatagramError::WrongDirection)
        ));
    }

    #[test]
    fn complete_datagram_authenticates_header() {
        let header = PacketHeader::new(PacketType::FrameChunk, 7, 9, 1);
        let (mut sender, mut receiver) = matching_pair();
        let mut datagram = sender.seal_datagram(&header, b"payload").unwrap();
        let (opened_header, opened_payload) = receiver.open_datagram(&datagram).unwrap();
        assert_eq!(opened_header, header);
        assert_eq!(opened_payload, b"payload");

        let (mut sender, mut receiver) = matching_pair();
        datagram = sender.seal_datagram(&header, b"payload").unwrap();
        datagram[3] ^= 1;
        assert!(receiver.open_datagram(&datagram).is_err());
        assert_eq!(header.encode().unwrap().len(), PacketHeader::SIZE);
    }
}

use crate::{codec::Decoder, CodecError, WireCodec};

pub const MAGIC: u16 = 0xec1d;
pub const PROTOCOL_VERSION: u8 = 3;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum PacketType {
    Handshake = 0,
    HandshakeAck = 1,
    FrameHeader = 2,
    FrameChunk = 3,
    CursorUpdate = 4,
    InputEvent = 5,
    Control = 6,
    Ping = 7,
    AudioFrame = 8,
    PairingRequest = 9,
    PairingGrant = 10,
    PairingReject = 11,
}

impl PacketType {
    pub const ALL: [Self; 12] = [
        Self::Handshake,
        Self::HandshakeAck,
        Self::FrameHeader,
        Self::FrameChunk,
        Self::CursorUpdate,
        Self::InputEvent,
        Self::Control,
        Self::Ping,
        Self::AudioFrame,
        Self::PairingRequest,
        Self::PairingGrant,
        Self::PairingReject,
    ];
}

impl TryFrom<u8> for PacketType {
    type Error = CodecError;

    fn try_from(value: u8) -> Result<Self, Self::Error> {
        match value {
            0 => Ok(Self::Handshake),
            1 => Ok(Self::HandshakeAck),
            2 => Ok(Self::FrameHeader),
            3 => Ok(Self::FrameChunk),
            4 => Ok(Self::CursorUpdate),
            5 => Ok(Self::InputEvent),
            6 => Ok(Self::Control),
            7 => Ok(Self::Ping),
            8 => Ok(Self::AudioFrame),
            9 => Ok(Self::PairingRequest),
            10 => Ok(Self::PairingGrant),
            11 => Ok(Self::PairingReject),
            unknown => Err(CodecError::UnknownPacketType(unknown)),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PacketHeader {
    pub packet_type: PacketType,
    pub sequence: u32,
    pub timestamp_ms: u32,
    pub flags: u8,
}

impl PacketHeader {
    pub const SIZE: usize = 12;

    pub const fn new(packet_type: PacketType, sequence: u32, timestamp_ms: u32, flags: u8) -> Self {
        Self {
            packet_type,
            sequence,
            timestamp_ms,
            flags,
        }
    }
}

impl WireCodec for PacketHeader {
    fn encode(&self) -> Result<Vec<u8>, CodecError> {
        let mut output = Vec::with_capacity(Self::SIZE);
        output.extend_from_slice(&MAGIC.to_le_bytes());
        output.push(self.packet_type as u8);
        output.extend_from_slice(&self.sequence.to_le_bytes());
        output.extend_from_slice(&self.timestamp_ms.to_le_bytes());
        output.push(self.flags);
        Ok(output)
    }

    fn decode(input: &[u8]) -> Result<Self, CodecError> {
        let mut decoder = Decoder::new(input);
        let magic = decoder.u16("packet magic")?;
        if magic != MAGIC {
            return Err(CodecError::InvalidMagic { found: magic });
        }
        let packet_type = PacketType::try_from(decoder.u8("packet type")?)?;
        let sequence = decoder.u32("packet sequence")?;
        let timestamp_ms = decoder.u32("packet timestamp")?;
        let flags = decoder.u8("packet flags")?;
        decoder.finish("packet header")?;
        Ok(Self {
            packet_type,
            sequence,
            timestamp_ms,
            flags,
        })
    }
}

use std::ops::{BitOr, BitOrAssign};

use crate::{
    codec::{checked_bytes, push_f32, push_u16, push_u64, usize_to_u16, Decoder},
    CodecError, WireCodec, PROTOCOL_VERSION,
};

pub const MAX_HANDSHAKE_NAME_BYTES: usize = 1024;
pub const MAX_PAIRING_ID_BYTES: usize = 256;
pub const SESSION_SALT_SIZE: usize = 16;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Capabilities(u64);

impl Capabilities {
    pub const STREAM_CONFIGURATION: Self = Self(1 << 0);
    pub const CLIPBOARD_SYNC: Self = Self(1 << 1);
    pub const TEXT_CLIPBOARD_SYNC: Self = Self(1 << 2);

    pub const fn empty() -> Self {
        Self(0)
    }

    pub const fn all() -> Self {
        Self(Self::STREAM_CONFIGURATION.0 | Self::CLIPBOARD_SYNC.0 | Self::TEXT_CLIPBOARD_SYNC.0)
    }

    pub const fn from_bits_retain(bits: u64) -> Self {
        Self(bits)
    }

    pub const fn bits(self) -> u64 {
        self.0
    }

    pub const fn contains(self, other: Self) -> bool {
        self.0 & other.0 == other.0
    }
}

impl BitOr for Capabilities {
    type Output = Self;

    fn bitor(self, rhs: Self) -> Self::Output {
        Self(self.0 | rhs.0)
    }
}

impl BitOrAssign for Capabilities {
    fn bitor_assign(&mut self, rhs: Self) {
        self.0 |= rhs.0;
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Handshake {
    pub name: String,
    pub width: u16,
    pub height: u16,
    pub scale: f32,
    pub version: u8,
    pub capabilities: Capabilities,
    pub pairing_id: String,
    pub session_salt: [u8; SESSION_SALT_SIZE],
}

impl WireCodec for Handshake {
    fn encode(&self) -> Result<Vec<u8>, CodecError> {
        if self.version != PROTOCOL_VERSION {
            return Err(CodecError::UnsupportedVersion(self.version));
        }
        let name = checked_bytes(&self.name, "handshake name", MAX_HANDSHAKE_NAME_BYTES)?;
        let pairing_id = checked_bytes(
            &self.pairing_id,
            "handshake pairing ID",
            MAX_PAIRING_ID_BYTES,
        )?;
        let mut output = Vec::with_capacity(37 + name.len() + pairing_id.len());
        push_u16(&mut output, usize_to_u16(name.len(), "handshake name")?);
        output.extend_from_slice(name);
        push_u16(&mut output, self.width);
        push_u16(&mut output, self.height);
        push_f32(&mut output, self.scale);
        output.push(self.version);
        push_u64(&mut output, self.capabilities.bits());
        push_u16(
            &mut output,
            usize_to_u16(pairing_id.len(), "handshake pairing ID")?,
        );
        output.extend_from_slice(pairing_id);
        output.extend_from_slice(&self.session_salt);
        Ok(output)
    }

    fn decode(input: &[u8]) -> Result<Self, CodecError> {
        let mut decoder = Decoder::new(input);
        let name_length = decoder.u16("handshake name length")? as usize;
        if name_length > MAX_HANDSHAKE_NAME_BYTES {
            return Err(CodecError::LengthLimit {
                field: "handshake name",
                actual: name_length,
                max: MAX_HANDSHAKE_NAME_BYTES,
            });
        }
        let name = decoder.utf8(name_length, "handshake name")?;
        let width = decoder.u16("handshake width")?;
        let height = decoder.u16("handshake height")?;
        let scale = decoder.f32("handshake scale")?;
        let version = decoder.u8("handshake version")?;
        if version != PROTOCOL_VERSION {
            return Err(CodecError::UnsupportedVersion(version));
        }
        let capabilities = Capabilities::from_bits_retain(decoder.u64("handshake capabilities")?);
        let pairing_id_length = decoder.u16("handshake pairing ID length")? as usize;
        if pairing_id_length > MAX_PAIRING_ID_BYTES {
            return Err(CodecError::LengthLimit {
                field: "handshake pairing ID",
                actual: pairing_id_length,
                max: MAX_PAIRING_ID_BYTES,
            });
        }
        let pairing_id = decoder.utf8(pairing_id_length, "handshake pairing ID")?;
        let salt = decoder.take(SESSION_SALT_SIZE, "handshake session salt")?;
        let mut session_salt = [0_u8; SESSION_SALT_SIZE];
        session_salt.copy_from_slice(salt);
        decoder.finish("handshake")?;
        Ok(Self {
            name,
            width,
            height,
            scale,
            version,
            capabilities,
            pairing_id,
            session_salt,
        })
    }
}

use crate::{
