}

pub trait PlatformClipboard: Send + Sync + 'static {
    fn snapshot(&self) -> Result<ClipboardSnapshot, ClipboardError>;
    fn set_text(&self, text: &str) -> Result<u64, ClipboardError>;
}

#[derive(Debug, Default, Clone)]
