    state: Arc<Mutex<ClipboardSnapshot>>,
}

impl Default for ClipboardSnapshot {
    fn default() -> Self {
        Self {
            change_count: 0,
            text: None,
            types: Vec::new(),
        }
    }
}

impl PlatformClipboard for MemoryClipboard {
    fn snapshot(&self) -> Result<ClipboardSnapshot, ClipboardError> {
        Ok(self.state.lock().expect("memory clipboard poisoned").clone())
    }

