    #[derive(Debug, Default, Clone, Copy)]
    pub struct SystemClipboard;

    impl PlatformClipboard for SystemClipboard {
        fn snapshot(&self) -> Result<ClipboardSnapshot, ClipboardError> {
            let pasteboard = unsafe { NSPasteboard::generalPasteboard() };
            let change_count = unsafe { pasteboard.changeCount() } as u64;
            let types = unsafe { pasteboard.types() }
                .map(|types| types.iter().map(ToString::to_string).collect())
                .unwrap_or_default();
            let text = unsafe { pasteboard.stringForType(NSPasteboardTypeString) }
                .map(|text| text.to_string());
            Ok(ClipboardSnapshot {
                change_count,
                text,
                types,
            })
        }

