        handshake_ack_timeout: Duration::from_secs(1),
    };
    let session = ClientSession::new(config).unwrap();
    assert!(matches!(
        session.pair_with_pin(pin),
        Err(SessionError::PairingRejected(
            PairingRejectReason::PairingDisabled
        ))
    ));
    server.join().unwrap();
